  function highlight(line){const re=/(\/\/.*$|"[^"\n]*"|'[^'\n]*'|\b(?:import|from|type|export|const|new|async|function|await|return|string|true|false)\b|\b\d+\b)/g;let out='',last=0;for(const m of line.matchAll(re)){out+=escape(line.slice(last,m.index));const t=m[0],cls=t.startsWith('//')?'comment':/^['"]/.test(t)?'string':/^\d/.test(t)?'number':'keyword';out+='<span class="'+cls+'">'+escape(t)+'</span>';last=m.index+t.length;}return out+escape(line.slice(last));}
